/* ── Scroll progress ── */
window.addEventListener('scroll',function(){
  var s=document.documentElement,b=document.body;
  var pct=(s.scrollTop||b.scrollTop)/(s.scrollHeight-s.clientHeight)*100;
  document.getElementById('sp').style.width=pct+'%';
  document.getElementById('mainNav').classList.toggle('scrolled',pct>1);
  document.getElementById('fabTop').classList.toggle('vis',(s.scrollTop||b.scrollTop)>400);
},{passive:true});

/* ── Mobile nav ── */
var navToggle=document.getElementById('navToggle');
var navMobile=document.getElementById('navMobile');
navToggle.addEventListener('click',function(){
  navToggle.classList.toggle('open');
  navMobile.classList.toggle('open');
  navToggle.setAttribute('aria-expanded',navMobile.classList.contains('open'));
  document.body.style.overflow=navMobile.classList.contains('open')?'hidden':'';
});
function closeMobile(){
  navToggle.classList.remove('open');
  navMobile.classList.remove('open');
  navToggle.setAttribute('aria-expanded','false');
  document.body.style.overflow='';
}

/* ── Scroll reveal + section title underline + counter ── */
var io=new IntersectionObserver(function(entries){
  entries.forEach(function(e){
    if(!e.isIntersecting)return;
    e.target.classList.add('on');
    /* Animated counter */
    e.target.querySelectorAll('.metric-val[data-target]').forEach(animateCounter);
    io.unobserve(e.target);
  });
},{threshold:.15});

document.querySelectorAll('.rv,.rv-left,.rv-right,.rv-scale,.sec-title').forEach(function(el){
  io.observe(el);
});

function animateCounter(el){
  var target=parseFloat(el.dataset.target);
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    el.textContent=target+(el.dataset.suffix||'');return;
  }
  var suffix=el.dataset.suffix||'';
  var isFloat=target%1!==0;
  var start=0,dur=1600,begin=null;
  function step(ts){
    if(!begin)begin=ts;
    var p=Math.min((ts-begin)/dur,1);
    var ease=1-Math.pow(1-p,3);
    var val=start+(target-start)*ease;
    el.textContent=(isFloat?val.toFixed(1):Math.floor(val))+suffix;
    if(p<1)requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

/* ── FAQ toggle ── */
function toggleFaq(btn){
  var item=btn.parentElement;
  var wasOpen=item.classList.contains('open');
  document.querySelectorAll('.faq-item.open').forEach(function(i){
    i.classList.remove('open');
    var b=i.querySelector('.faq-q');
    if(b)b.setAttribute('aria-expanded','false');
  });
  if(!wasOpen){item.classList.add('open');btn.setAttribute('aria-expanded','true');}
}

/* ── Canvas particles + orbs ── */
(function(){
  var c=document.getElementById('dotCanvas');
  if(!c)return;
  var ctx=c.getContext('2d');
  var W,H,pts=[],orbs=[];
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){c.style.display='none';return;}
  var mobile=window.innerWidth<640;

  function resize(){
    W=c.width=window.innerWidth;
    H=c.height=window.innerHeight;
  }
  resize();
  window.addEventListener('resize',function(){resize();mobile=window.innerWidth<640;},{passive:true});

  /* Particles */
  var NPTS=mobile?40:80;
  for(var i=0;i<NPTS;i++){
    pts.push({
      x:Math.random()*W,y:Math.random()*H,
      vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.35,
      r:Math.random()*1.6+.4
    });
  }

  /* Orbs */
  var ORB_DATA=[
    {x:.15,y:.25,r:280,c:'rgba(41,151,255,'},
    {x:.8, y:.7, r:220,c:'rgba(48,209,88,'},
    {x:.65,y:.2, r:200,c:'rgba(191,90,242,'},
    {x:.3, y:.8, r:190,c:'rgba(255,159,10,'}
  ];
  var orbsToUse=mobile?ORB_DATA.slice(0,2):ORB_DATA;
  orbsToUse.forEach(function(o){
    orbs.push({
      bx:o.x*W,by:o.y*H,
      x:o.x*W,y:o.y*H,
      r:mobile?o.r*.6:o.r,c:o.c,
      t:Math.random()*Math.PI*2,
      sp:.002+Math.random()*.002,
      amp:mobile?20:40+Math.random()*30
    });
  });

  var DIST=mobile?90:130;
  var raf;
  function draw(){
    ctx.clearRect(0,0,W,H);
    /* orbs */
    orbs.forEach(function(o){
      o.t+=o.sp;
      o.x=o.bx+Math.cos(o.t)*o.amp;
      o.y=o.by+Math.sin(o.t*1.3)*o.amp;
      var g=ctx.createRadialGradient(o.x,o.y,0,o.x,o.y,o.r);
      g.addColorStop(0,o.c+'.08)');
      g.addColorStop(1,o.c+'0)');
      ctx.fillStyle=g;
      ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,Math.PI*2);ctx.fill();
    });
    /* particles + lines */
    for(var i=0;i<pts.length;i++){
      var p=pts[i];
      p.x+=p.vx;p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1;
      if(p.y<0||p.y>H)p.vy*=-1;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fillStyle='rgba(255,255,255,.5)';
      ctx.fill();
      if(!mobile){for(var j=i+1;j<pts.length;j++){
        var q=pts[j];
        var dx=p.x-q.x,dy=p.y-q.y;
        var dist=Math.sqrt(dx*dx+dy*dy);
        if(dist<DIST){
          ctx.beginPath();
          ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);
          ctx.strokeStyle='rgba(255,255,255,'+(1-dist/DIST)*.12+')';
          ctx.lineWidth=.6;ctx.stroke();
        }
      }}
    }
    raf=requestAnimationFrame(draw);
  }
  draw();
  /* Pause when tab hidden to save resources */
  document.addEventListener('visibilitychange',function(){
    if(document.hidden)cancelAnimationFrame(raf);else draw();
  });
})();

